<?php /** @package Meridian_News */ $author_id = get_the_author_meta( 'ID' ); ?>
<section class="author-box"><h2><?php esc_html_e( 'About the author', 'meridian-news' ); ?></h2><div class="author-box__body"><?php echo get_avatar( $author_id, 88 ); ?><div><h3><a href="<?php echo esc_url( get_author_posts_url( $author_id ) ); ?>"><?php echo esc_html( get_the_author_meta( 'display_name', $author_id ) ); ?></a></h3><?php if ( get_the_author_meta( 'description', $author_id ) ) { ?><p><?php echo esc_html( get_the_author_meta( 'description', $author_id ) ); ?></p><?php } ?><a class="text-link" href="<?php echo esc_url( get_author_posts_url( $author_id ) ); ?>"><?php esc_html_e( 'View all articles', 'meridian-news' ); ?></a></div></div></section>
